def g8():
    o=''
    for i,t in enumerate(('ADD','LOAD','MUL','STORE')):o+=T(80+i*68,14,t,'t-s t-b')
    rows=[['u=d+e','x=[p]','m=a·b',None],['s=x+c',None,None,None],['t=s+m',None,None,None],[None,None,None,'[r]=t']]
    hi={(0,1),(1,0),(2,0),(3,3)}
    for r,row in enumerate(rows):
        y=22+r*32;o+=TL(6,y+19,f'сөз {r+1}','t-s mu')
        for c,v in enumerate(row):
            x=48+c*68
            if v is None:o+=B(x,y,64,28,'NOP','soft','t-s mu',r=4)
            else:o+=B(x,y,64,28,v,'bxa' if (r,c) in hi else 'bx','t-s',r=4)
    o+=T(180,164,'бояулы тізбек: x → s → t → [r] — 4 сөзден азға жол жоқ','t-s ac')
    return o
